    }
    int status;
    {
        memset((void *)&gpsdata, 0, sizeof(gpsdata));
        status = libgps_json_unpack((char *)Data, &gpsdata, NULL);
    }
    {
        memset((void *)&gpsdata, 0, sizeof(gpsdata));
        status = json_toff_read((char *)Data, &gpsdata, NULL);
    }

    return status;
}

